package com.adria.transaction.messaging;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.slf4j.Logger;import org.slf4j.LoggerFactory;@Component public class TransactionConsumer{private static final Logger log=LoggerFactory.getLogger(TransactionConsumer.class);@KafkaListener(topics="bank.transactions.created",groupId="bank-audit") public void consume(TransactionEvent e){log.info("TransactionCreated reçue: eventId={}, transactionId={}, accountId={}, amount={} {}",e.eventId(),e.transactionId(),e.accountId(),e.amount(),e.currency());}}